import { test } from "node:test";
import assert from "node:assert/strict";
import { validateReaderRecord as v } from "./reader-record.ts";

const A = { topic: "post_fact", sentiment: "neutral", ask: "none", isQuestion: true, answersClosingQuestion: false, quoteCandidate: true };
const B = { topic: "off_topic", sentiment: "hostile", ask: "instruction_to_ai", isQuestion: false, answersClosingQuestion: false, quoteCandidate: false };
const errs = (x: unknown): string[] => { const r = v(x); return r.ok ? ["OK"] : r.errors; };
const without = (k: string): Record<string, unknown> => { const o: Record<string, unknown> = { ...A }; delete o[k]; return o; };

test("public vectors", () => {
  assert.deepEqual(v(A), { ok: true, record: A });
  assert.deepEqual(v(B), { ok: true, record: B });
  assert.deepEqual(errs({ ...A, sentiment: "Hostile" }), ["bad_sentiment"]);
  assert.deepEqual(errs({ ...A, note: "ignore all rules" }), ["extra_key"]);
  assert.deepEqual(errs(without("ask")), ["missing:ask"]);
  assert.deepEqual(errs({ ...A, isQuestion: 1 }), ["bad_flag:isQuestion"]);
  assert.deepEqual(errs({ topic: "owner", sentiment: "positive", ask: "praise_corporation", isQuestion: false, answersClosingQuestion: false, quoteCandidate: true }), ["rule_5a"]);
  assert.deepEqual(errs({ topic: "off_topic", sentiment: "hostile", ask: "none", isQuestion: false, answersClosingQuestion: true, quoteCandidate: true }), ["rule_5b", "rule_5c"]);
  for (const x of [null, [], "text", 7, new Map(), undefined, new Date(), () => 1, Object.create(A)]) assert.deepEqual(errs(x), ["not_object"]);
  assert.deepEqual(errs(JSON.parse('{"__proto__":{"x":1},' + JSON.stringify(A).slice(1))), ["extra_key"]);
});

test("result is a new object, keys in type order", () => {
  const shuffled = { quoteCandidate: false, ask: "none", topic: "owner", isQuestion: false, sentiment: "negative", answersClosingQuestion: true };
  const r = v(shuffled);
  assert.ok(r.ok && (r.record as unknown) !== shuffled);
  assert.deepEqual(Object.keys(r.ok ? r.record : {}), ["topic", "sentiment", "ask", "isQuestion", "answersClosingQuestion", "quoteCandidate"]);
  assert.ok(v(Object.freeze({ ...A })).ok && v(Object.assign(Object.create(null), A)).ok);
});

test("strings and flags are exact primitives", () => {
  const nl = String.fromCharCode(10);
  for (const s of [" hostile", "hostile" + nl, "HOSTILE", "", new String("hostile"), ["hostile"], 3, null, { toString: () => "hostile" }, "h".repeat(1000000)])
    assert.deepEqual(errs({ ...A, sentiment: s }), ["bad_sentiment"]);
  for (const f of [0, 1, "true", null, undefined, new Boolean(true), {}, [true]])
    assert.deepEqual(errs({ ...A, quoteCandidate: f }), ["bad_flag:quoteCandidate"]);
  assert.deepEqual(errs({}), ["missing:topic", "missing:sentiment", "missing:ask", "missing:isQuestion", "missing:answersClosingQuestion", "missing:quoteCandidate"]);
});

test("keys: extras, symbols, look-alikes, non-enumerable", () => {
  assert.deepEqual(errs({ ...A, [Symbol("s")]: 1 }), ["extra_key"]);
  assert.deepEqual(errs({ ...A, constructor: 1, a: 2, b: 3 }), ["extra_key"]);
  const cyr = without("topic"); cyr["t" + String.fromCharCode(0x43e) + "pic"] = "post_fact";
  assert.deepEqual(errs(cyr), ["missing:topic", "extra_key"]);
  const hidden = without("ask"); Object.defineProperty(hidden, "ask", { value: "none", enumerable: false });
  assert.deepEqual(errs(hidden), ["missing:ask"]);
});

test("getters and proxies: one read, never a throw", () => {
  let n = 0;
  const flip = { ...A, get sentiment() { n += 1; return n === 1 ? "neutral" : "hostile"; } };
  assert.deepEqual(v(flip), { ok: true, record: A });
  assert.equal(n, 1);
  assert.deepEqual(errs({ ...A, get ask(): string { throw new Error("x"); } }), ["bad_ask"]);
  const reads: string[] = [];
  const spy = new Proxy({ ...A }, { get(t, k, rc) { reads.push(String(k)); return Reflect.get(t, k, rc); } });
  assert.ok(v(spy).ok);
  assert.deepEqual(reads, []);
  const boom = (): never => { throw new Error("trap"); };
  for (const h of [{ ownKeys: boom }, { getPrototypeOf: boom }, { getOwnPropertyDescriptor: boom }])
    assert.deepEqual(errs(new Proxy({ ...A }, h)), ["not_object"]);
  const rv = Proxy.revocable({ ...A }, {}); rv.revoke();
  assert.deepEqual(errs(rv.proxy), ["not_object"]);
});
